import json

# Scale 1.4B per-pair JSON
with open('results/generalize/pythia14b_wiki_a100_s42/analysis/pythia14b_8pair_6method_analysis.json') as f:
    d = json.load(f)

print('=== SCALE 1.4B s42: Per-pair details (6-method analysis) ===')
for pair in d['canonical_pairs']:
    methods = d['per_pair'][pair]
    print(f'\n--- {pair} (K={d[\"pair_votes\"][pair]}) ---')
    for m in ['naive_pearson','diff_xcorr','threshold_onset','perm_granger_fwd','perm_granger_rev','toda_yamamoto']:
        md = methods[m]
        p = md.get('p_value')
        s = md.get('significant', False)
        extras = []
        if 'r' in md: extras.append(f'r={md[\"r\"]:.4f}')
        if 'lag' in md: extras.append(f'lag={md[\"lag\"]}')
        if 'lead_time' in md: extras.append(f'lead={md[\"lead_time\"]}')
        if 'f_stat' in md: extras.append(f'F={md[\"f_stat\"]:.4f}')
        if 'wald_F' in md: extras.append(f'W={md[\"wald_F\"]:.4f}')
        if 'd_max' in md: extras.append(f'd_max={md[\"d_max\"]}')
        if 'df_resid' in md: extras.append(f'df_resid={md[\"df_resid\"]}')
        p_str = f'{p:.6f}' if isinstance(p, float) else str(p)
        print(f'  {m:20s}: p={p_str:12s} sig={str(s):5s} {\" \".join(extras)}')

print(f'\npair_votes: {json.dumps(d[\"pair_votes\"])}')
print(f'method_sig: {json.dumps(d[\"method_sig_counts\"])}')
print(f'\ntrajectory:')
for metric, vals in d['trajectory'].items():
    print(f'  {metric}: gen0={vals[\"gen0\"]:.6f} gen10={vals[\"gen10\"]:.6f} drift={vals[\"drift_pct\"]:.1f}%')
"

